class Solution:
    def validStrings(self, n: int, k: int) -> List[str]:
        res = []
        def bt(i, cost, prev, s):
            if i == n:
                res.append(s)
                return
            bt(i + 1, cost, False, s + '0')
            if not prev and cost + i <= k:
                bt(i + 1, cost + i, True, s + '1')
        bt(0, 0, False, '')
        return res

