class Solution {
public:
    vector<string> validStrings(int n, int k) {
        vector<string> res;
        string s;
        function<void(int,int,bool)> bt = [&](int i, int cost, bool prev) {
            if (i == n) { res.push_back(s); return; }
            s.push_back('0');
            bt(i + 1, cost, false);
            s.back() = '1';
            if (!prev && cost + i <= k) bt(i + 1, cost + i, true);
            s.pop_back();
        };
        bt(0, 0, false);
        return res;
    }
};

