class Solution {
    private List<String> res = new ArrayList<>();
    private char[] s;
    private int n, k;
    public List<String> validStrings(int n, int k) {
        this.n = n; this.k = k;
        this.s = new char[n];
        bt(0, 0, false);
        return res;
    }
    private void bt(int i, int cost, boolean prev) {
        if (i == n) { res.add(new String(s)); return; }
        s[i] = '0';
        bt(i + 1, cost, false);
        if (!prev && cost + i <= k) {
            s[i] = '1';
            bt(i + 1, cost + i, true);
        }
    }
}

