class Solution:
    def validStrings(self, n: int, k: int) -> List[str]:
        res = []
        for mask in range(1 << n):
            if mask & (mask << 1):
                continue
            cost = sum(i for i in range(n) if mask >> i & 1)
            if cost <= k:
                res.append(''.join('1' if mask >> i & 1 else '0' for i in range(n)))
        return res

