class Solution {
public:
    vector<string> validStrings(int n, int k) {
        vector<string> res;
        for (int mask = 0; mask < (1 << n); mask++) {
            if (mask & (mask << 1)) continue;
            int cost = 0;
            for (int i = 0; i < n; i++) if (mask >> i & 1) cost += i;
            if (cost > k) continue;
            string s(n, '0');
            for (int i = 0; i < n; i++) if (mask >> i & 1) s[i] = '1';
            res.push_back(s);
        }
        return res;
    }
};

