class Solution {
    public List<String> validStrings(int n, int k) {
        List<String> res = new ArrayList<>();
        for (int mask = 0; mask < (1 << n); mask++) {
            if ((mask & (mask << 1)) != 0) continue;
            int cost = 0;
            for (int i = 0; i < n; i++) if (((mask >> i) & 1) == 1) cost += i;
            if (cost > k) continue;
            char[] s = new char[n];
            Arrays.fill(s, '0');
            for (int i = 0; i < n; i++) if (((mask >> i) & 1) == 1) s[i] = '1';
            res.add(new String(s));
        }
        return res;
    }
}

